const Flipper = styled.svg`
  transform: scaleY(${({flip}:{flip: boolean}) => flip ? -1 : 1 });
`

const Arrow = ({up}: {up: boolean}) => {
	const {theme} = useContext(AppContext).settings
	const color = theme === Themes.DARK ? COLORS.grey2 : COLORS.grey5
	return (
		<Flipper
			flip={!up}
			width="17"
			height="19"
			viewBox="0 0 17 19"
			fill="none"
			xmlns="http://www.w3.org/2000/svg"
		>
			<g clipPath="url(#clip0_951_17115)">
				<path d="M11.56 11.149L8.5 8.09571L5.44 11.149L4.5 10.209L8.5 6.20905L12.5 10.209L11.56 11.149Z" fill={color}/>
			</g>
			<defs>
				<clipPath id="clip0_951_17115">
					<rect width="16" height="16" fill="white" transform="translate(16.5 16.8757) rotate(180)"/>
				</clipPath>
			</defs>
		</Flipper>
	)
}

